#!/usr/bin/env python3
"""Build a lightweight offline review page. Uses relative images, never base64."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
assets = json.loads((ROOT / 'art/manifest.json').read_text())['assets']
groups = {}
for asset in assets:
    parts = Path(asset['file']).parts
    group = parts[2] if parts[1] == 'characters' else parts[1]
    groups.setdefault(group, []).append(asset)

catalog = []
for group, items in groups.items():
    cards = []
    for item in items:
        filename = html.escape(item['file'])
        label = html.escape(Path(item['source']).stem.replace('-', ' '))
        cards.append(f'<a class="asset" href="{filename}"><div class="checker"><img loading="lazy" src="{filename}" alt="{label}"></div><span>{label}</span><small>{item["width"]} × {item["height"]} · WebP</small></a>')
    catalog.append(f'<details><summary>{html.escape(group.title())} <small>{len(items)} images</small></summary><div class="assets">{"".join(cards)}</div></details>')

page = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Wishweave · Connected World Handoff</title>
<style>
:root{color-scheme:dark;--ink:#fff5e3;--muted:#c9bcae;--gold:#e8bd78;--line:#5d483b;--teal:#86ddd3;--panel:#30221f}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#1c1516;color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--teal);text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid var(--gold);outline-offset:5px}main{max-width:1180px;margin:auto;padding:48px 24px 80px}header{max-width:820px;margin-bottom:36px}.eyebrow{color:var(--gold);font-size:12px;letter-spacing:.17em;font-weight:700;text-transform:uppercase}h1{font:700 clamp(34px,6vw,62px)/1.08 Georgia,serif;margin:14px 0 20px}h2{font-size:25px;line-height:1.2;margin:0 0 18px}h3{font-size:18px;margin:0 0 8px}p{margin:0 0 16px}.lead{font-size:19px;color:#eadccd}.muted,small{color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}.button{display:inline-flex;align-items:center;min-height:48px;padding:9px 15px;background:#493328;border:1px solid var(--line);border-radius:10px;text-decoration:none;color:var(--ink);font-weight:650}.primary{background:#14675e;border-color:#3c9387}.callout{padding:20px 24px;border-left:3px solid var(--gold);background:var(--panel);border-radius:0 12px 12px 0;margin:24px 0}.callout p:last-child{margin:0}section{margin-top:56px;scroll-margin-top:24px}.previews{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}figure{margin:0;min-width:0}figure>a{display:block}figure img{display:block;width:100%;height:auto;border-radius:14px;border:1px solid var(--line)}figcaption{padding:16px 3px 0}.number{font-size:12px;color:var(--gold);font-weight:700;letter-spacing:.1em}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{border:1px solid var(--line);border-radius:14px;background:var(--panel);padding:24px}.panel ul{padding-left:20px;margin:8px 0 0}.panel li{margin:6px 0}table{border-collapse:collapse;width:100%}td,th{text-align:left;vertical-align:top;padding:14px 0;border-bottom:1px solid var(--line)}td:first-child{width:34%;padding-right:20px;color:var(--gold);font-weight:650}.map{width:100%;max-height:620px;object-fit:contain;object-position:top;background:#f8f1e7;border-radius:12px;display:block}.files{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}details{border:1px solid var(--line);border-radius:12px;margin:12px 0;background:var(--panel)}summary{cursor:pointer;padding:18px;font-size:18px;font-weight:650;min-height:56px}summary small{font-size:13px;margin-left:10px;font-weight:400}.assets{padding:0 18px 20px;display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:14px}.asset{display:block;text-decoration:none;min-width:0}.checker{background-color:#ded3c4;background-image:linear-gradient(45deg,#cbc0b2 25%,transparent 25%),linear-gradient(-45deg,#cbc0b2 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#cbc0b2 75%),linear-gradient(-45deg,transparent 75%,#cbc0b2 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0;border-radius:8px}.asset img{width:100%;height:140px;object-fit:contain;padding:8px;display:block}.asset span{display:block;margin-top:8px;color:var(--ink);overflow-wrap:anywhere;line-height:1.35}.asset small{font-size:12px}.footer{border-top:1px solid var(--line);padding-top:24px;margin-top:56px;font-size:13px}.steps{padding-left:22px}.steps li{padding:0 0 12px 8px}code{overflow-wrap:anywhere;color:#f0d0a3;font-size:.9em}.proof{font-size:17px} @media(max-width:680px){main{padding:30px 18px 50px}.previews{grid-template-columns:1fr;gap:32px}.previews figure{max-width:420px;margin:auto}.columns{grid-template-columns:1fr}h1{font-size:39px}.panel{padding:20px}.map{max-height:none}td:first-child{width:38%}nav{gap:8px}}
</style></head><body><main>
<header><div class="eyebrow">Wishweave Wonders · Level 1</div><h1>One world.<br>One continuous race.</h1><p class="lead">Purl and Loop run from the opening rug, around connected bends, through the loom city and across the flower-gate finish. The next area comes into view as the camera follows them.</p><nav><a class="button primary" href="CLAUDIA-PROMPT.txt">Read Claudia’s brief</a><a class="button" href="#targets">Screen targets</a><a class="button" href="#course">Course foundation</a><a class="button" href="#assets">Art assets</a></nav></header>
<div class="callout"><p><strong>Construction handoff, not a finished game.</strong> The images below are visual targets. The included 3D course is a simplified connected layout. Production scenery, natural character animation, game integration and Android testing remain.</p></div>
<section id="targets"><div class="eyebrow">Current visual direction</div><h2>The opening, the connected turn and the finish</h2><p class="muted">Select an image to inspect it at full resolution. These are concept renders, not screenshots proving that the game runs.</p><div class="previews">
<figure><a href="references/01-opening-target.webp"><img src="references/01-opening-target.webp" width="841" height="1870" alt="Opening concept: red Purl and teal Loop race away along a wide embroidered road that curves around a tower."></a><figcaption><div class="number">01 · OPENING</div><h3>Run onto the supported rug</h3><p class="muted">Feet meet the road surface. Both racers share the world. The bend is already visible ahead.</p></figcaption></figure>
<figure><a href="references/02-connected-turn-target.webp"><img src="references/02-connected-turn-target.webp" width="841" height="1870" alt="Connected turn concept: the camera follows red Purl into the next area with teal Loop ahead on the same continuous road."></a><figcaption><div class="number">02 · CONTINUOUS TURN</div><h3>The camera travels with Purl</h3><p class="muted">Purl rounds the tower into the next part of Level 1. There is no page flip, reset or unsupported crossing.</p></figcaption></figure>
<figure><a href="references/03-finish-target.webp"><img src="references/03-finish-target.webp" width="841" height="1870" alt="Finish approach concept: both yarn racers approach the flower gate and a clearly visible finish band."></a><figcaption><div class="number">03 · FINISH APPROACH</div><h3>Cross the line to finish</h3><p class="muted">Three different threads are required. Each racer must physically cross the marked gate threshold.</p></figcaption></figure>
</div></section>
<section id="controls"><div class="columns"><div class="panel"><h2>Simple controls, natural movement</h2><table><tbody><tr><td>Normally</td><td>Purl runs automatically at a moderately brisk pace.</td></tr><tr><td>Swipe left / right</td><td>Steer within the road; choose a branch at a junction.</td></tr><tr><td>Swipe up</td><td>Jump. One gesture, one action.</td></tr><tr><td>Double-tap</td><td>Stop or resume Purl. Loop keeps racing.</td></tr><tr><td>Pause button</td><td>Pause both racers and the world.</td></tr></tbody></table></div><div class="panel"><h2>What makes the race feel right</h2><ul><li>Alternating foot plants and push-offs match actual distance traveled.</li><li>The body leans into turns; the camera follows smoothly behind.</li><li>Purl stops in an idle pose, without running in place.</li><li>Loop has independent movement, decisions and reactions.</li><li>If Purl slows down, Loop can pass. Results are not forced.</li><li>The next area is visible before entry. The world never switches pages.</li></ul><p style="margin-top:18px"><a href="docs/MOTION-AND-CAMERA.txt">Read the movement and camera contract</a></p></div></div></section>
<section id="course"><div class="eyebrow">Actual 3D source included</div><h2>A connected route from start to finish</h2><div class="columns"><a href="scenery/course-overhead.svg"><img class="map" src="scenery/course-overhead.svg" alt="Overhead construction plan of the continuous six-section route and connected branch."></a><div><p>The GLB contains a roughly <strong>201 m main road</strong>, one connected side path, six continuous areas and simple named landmarks. The overhead plan is generated from the same route data.</p><p>Use this to establish supported surfaces and connections, then dress it in the approved crochet-city art. The simple geometry is not the ornate scenery in the concept images.</p><div class="files"><a class="button" href="scenery/level1-connected-layout.glb" download>3D layout · GLB</a><a class="button" href="scenery/route.json">Route data</a><a class="button" href="scenery/README.md">Import notes</a></div><div class="callout"><p>Production work still includes materials, decoration, collision setup, character rigs or sufficient directional poses, camera integration and gameplay.</p></div><p><a href="scenery/validation.json">Spatial validation</a> · <a href="scenery/generate_course.py">Reusable generator</a></p></div></div></section>
<section id="assets"><div class="eyebrow">Reused from the earlier visual kit</div><h2>47 character, prop, feature and interface images</h2><p class="muted">Individual art is lossless WebP with the original decoded pixels preserved. These are 2D images, not rigged 3D models. Review alpha edges and foot/hand anchors before production use.</p>__CATALOG__<p><a href="art/manifest.json">Art provenance and dimensions</a> · <a href="docs/ASSET-GAPS.txt">What still needs to be created</a></p></section>
<section><div class="columns"><div class="panel"><h2>Implementation references</h2><p>Small dependency-free modules emit touch intents, sample the route and advance distance-driven motion. The engine owns physics, animation and race state.</p><ul><li><a href="code/README.md">Touch controls and integration</a></li><li><a href="code/touch-input.mjs">Touch input module</a></li><li><a href="code/ROUTE-MOTION.txt">Movement integration notes</a></li><li><a href="code/route-motion.mjs">Route and movement module</a></li><li><a href="docs/VERIFICATION.json">Verification scope and results</a></li></ul></div><div class="panel"><h2>Legacy world references</h2><p>The seven older paintings preserve materials, embroidery and landmark design. Use them as visual references, not as disconnected gameplay pages.</p><ul><li><a href="references/legacy-world-art/01-ribbon.webp">Rug and tower</a></li><li><a href="references/legacy-world-art/02-shortcut.webp">Raised crossing</a></li><li><a href="references/legacy-world-art/03-tassels.webp">Tassels</a></li><li><a href="references/legacy-world-art/04-snagged.webp">Snagling area</a></li><li><a href="references/legacy-world-art/05-recovery.webp">Recovery area</a></li><li><a href="references/legacy-world-art/06-butterfly.webp">Butterfly area</a></li><li><a href="references/legacy-world-art/07-finish.webp">Flower gate</a></li></ul></div></div></section>
<section><div class="eyebrow">First playable proof</div><h2>Check the movement before expanding the whole level</h2><ol class="steps"><li>Import or adapt the route and build the opening rug, tower bend and entry into the next area.</li><li>Demonstrate steering, a grounded jump, stopping while Loop passes, and resuming—all in an uninterrupted run.</li><li>Show the playable build and recording from the same source version. Verify foot contact, camera continuity, depth and Android screen fit.</li><li>After that foundation is accepted, extend through all six connected areas and finish the three pickups, Snagling, butterfly and race results.</li></ol><p class="proof"><a class="button primary" href="docs/ACCEPTANCE.txt">Open the full acceptance checklist</a></p></section>
<div class="footer"><p>Extract every numbered ZIP into the same parent folder, then open this page. The HTML uses relative images and contains no giant embedded screenshot data. The source modules require a host application; this page itself works offline.</p><p>Saved-rewards artwork is a locked visual placeholder. This kit contains no real-money payout service and no finished Android APK.</p></div>
</main></body></html>'''
(ROOT / 'index.html').write_text(page.replace('__CATALOG__', '\n'.join(catalog)), encoding='utf-8')
print(f'Wrote index.html with {len(assets)} art assets.')
